// Simple game mechanic: one nurse treats one accessible severe casualty at a time.
export function tickNursing(e,c,minutes,emit){e.nursingPatient=null;if(!c.reconComplete)return;const p=c.patients?.find(p=>p.severe&&!p.trapped&&!p.evacuated&&!p.nursingComplete);if(!p)return;e.nursingPatient=c.patients.indexOf(p);p.nursingUnit=e.id;p.nursingProgress=Math.min(1,(p.nursingProgress||0)+minutes/8);if(p.nursingProgress>=1){p.nursingComplete=true;emit('Soins infirmiers terminés. La prise en charge par le VSAV est facilitée.');}}
export function nursingMultiplier(p){return p?.severe&&p.nursingComplete?1.25:1;}
